def gen(draw):
    n = draw(st.integers(1, 12))
    alphabet = draw(st.sampled_from(["WA", "WAC", "WAB", "W", "A", "WACX"]))
    s = draw(st.lists(st.sampled_from(list(alphabet)), min_size=n, max_size=n))
