def validate(inp):
    lines = inp.split("\n")
    if len(lines) < 1:
        return False
    s = lines[0]
    if len(lines) > 2 or (len(lines) == 2 and lines[1] != ""):
        return False
    if not (1 <= len(s) <= 3 * 10**5):
