    return all("A" <= c <= "Z" for c in s)

def ref(inp):
    s = inp.split("\n")[0]
    cur = list(s)
    while True:
        t = "".join(cur)
        i = t.find("WA")
        if i == -1:
            break
        cur[i] = "A"
        cur[i + 1] = "C"
